def _ensure_programmer_executable():
    """ Find the lpc21isp executable and ensure it is executable
    """
    global _lpc21isp_executable
    if _lpc21isp_executable is None:
        _lpc21isp_executable = find_executable('lpc21isp')
        if _lpc21isp_executable is None:
            raise RuntimeError('Could not find lpc21isp executable')
        if not os.access(_lpc21isp_executable, os.X_OK):
            os.chmod(_lpc21isp_executable, os.stat(_lpc21isp_executable).st_mode | stat.S_IXUSR)

